<?php $files=glob(__DIR__.'/../backups/*.sql');rsort($files); ?>
<div class="card panel"><h3>Backup Database Otomatis</h3><p class="muted">Klik backup manual atau pasang Windows Task Scheduler menggunakan file scripts\backup_database.bat.</p><form method="post" action="actions/backup_database.php"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><button class="btn primary">Buat Backup Sekarang</button></form></div>
<div class="card panel"><h3>Daftar Backup</h3><table><thead><tr><th>File</th><th>Ukuran</th><th>Waktu</th><th>Unduh</th></tr></thead><tbody><?php foreach($files as $f):?><tr><td><?=e(basename($f))?></td><td><?=number_format(filesize($f)/1024,1)?> KB</td><td><?=date('d-m-Y H:i',filemtime($f))?></td><td><a href="backups/<?=e(basename($f))?>">Unduh</a></td></tr><?php endforeach;?></tbody></table></div>
